#include <algorithm>
#include <cmath>
#include <cstring>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
#include <net.h>
bool loadf(const std::string&p,std::vector<float>&v,size_t n){v.resize(n);std::ifstream f(p,std::ios::binary);f.read((char*)v.data(),n*4);return f&&f.gcount()==(std::streamsize)(n*4);}std::vector<float> rev(const std::vector<float>&x){std::vector<float>o(32768);for(int z=0;z<4;z++)for(int n=0;n<64;n++)for(int c=0;c<32;c++){int t=n/16,h=(n/4)%4,w=n%4;o[((t*8+(z/2)*4+h)*8+(z%2)*4+w)*32+c]=x[(z*64+n)*32+c];}return o;}bool cmp(const char*s,const std::vector<float>&a,const std::vector<float>&b){float m=0;double q=0;size_t nan=0,inf=0;for(size_t i=0;i<a.size();i++){float e=std::fabs(a[i]-b[i]);m=std::max(m,e);q+=e;nan+=std::isnan(a[i]);inf+=std::isinf(a[i]);}std::cout<<s<<" max_abs_error="<<m<<" mean_abs_error="<<q/a.size()<<" nan_count="<<nan<<" inf_count="<<inf<<"\n";return m<1e-4&&!nan&&!inf;}int main(int ac,char**av){if(ac!=2)return 2;std::string r=av[1];std::vector<float>x,m,c,s,ew,eo;if(!loadf(r+"/windows.bin",x,8192)||!loadf(r+"/reference_mask.bin",m,16384)||!loadf(r+"/reference_rope_cos.bin",c,256)||!loadf(r+"/reference_rope_sin.bin",s,256)||!loadf(r+"/reference_windows.bin",ew,8192)||!loadf(r+"/reference_output.bin",eo,8192))return 3;ncnn::Net n;n.opt.use_packing_layout=false;if(n.load_param((r+"/model.ncnn.param").c_str())||n.load_model((r+"/model.ncnn.bin").c_str()))return 4;ncnn::Mat a(32,64,4),b(64,64,4),d(4,64),e(4,64),y;std::memcpy(a.data,x.data(),32768);std::memcpy(b.data,m.data(),65536);std::memcpy(d.data,c.data(),1024);std::memcpy(e.data,s.data(),1024);auto ex=n.create_extractor();int r0=ex.input("in0",a),r1=ex.input("in1",b),r2=ex.input("in2",d),r3=ex.input("in3",e),re=ex.extract("out0",y);std::cerr<<"input_rets="<<r0<<","<<r1<<","<<r2<<","<<r3<<" extract_ret="<<re<<"\n";if(r0||r1||r2||r3||re||y.total()!=8192)return 5;std::vector<float>o(8192);std::memcpy(o.data(),y.data,32768);bool ok=cmp("core_windows",o,ew)&&cmp("reverse_bthwc",rev(o),eo);std::cout<<"ncnn_perhead_direct_runner="<<(ok?"PASS":"FAIL")<<"\n";return ok?0:1;}
